fallback={'furniture':('living-room','Armchairs & Accent Chairs'),'lighting':('lighting','Ceiling Lights'),'rugs':('rugs','Area Rugs'),'decor':('decor','Decorative Objects'),'bedding-bath':('bedding','Sheet Sets'),'kitchen':('kitchen','Kitchen Utensils'),'appliances':('appliances','Home Appliances'),'outdoor':('outdoor','Patio Seating'),'storage':('storage','Storage Bins'),'home-office':('office','Office Accessories'),'baby-kids':('kids','Kids Décor'),'pets':('pet','Pet Accessories'),'home-improvement':('improvement','Tools'),'seasonal':('seasonal','Seasonal Décor')}
