base={'living-room':2200,'bedroom':3400,'dining':1800,'outdoor':950,'lighting':650,'rugs':850,'decor':380,'bedding':450,'bath':280,'kitchen':350,'appliances':1200,'storage':400,'office':1300,'kids':450,'improvement':250,'pet':350,'seasonal':220}
price_rules=[(r'sofa|sectional',7500),(r'recliner',5400),(r'chair',1800),(r'dining.*table',3800),(r'coffee table',1600),(r'floor lamp',1100),(r'table lamp',650),(r'mattress',3500),(r'bed frame|platform bed',3200),(r'light bulb',80),(r'curtain',350),(r'throw pillow|cushion',180),(r'dinnerware.*set',550),(r'kettle',450),(r'refrigerator',4200),(r'coffee maker',850),(r'toilet brush',120)]
for p in items:
 old=p['department'];name=p['name'].lower();d,s=fallback[old]
 for pattern,dept,sub in rules.get(old,[]):
  if re.search(pattern,name):d,s=dept,sub;break
 p['department']=d;p['subcategory']=s
 b=base[d]
 for pattern,v in price_rules:
  if re.search(pattern,name):b=v;break
 # Category-level illustrative planning estimates; never represented as merchant price history.
 p['price']=int(round(b*(.8+(int(hashlib.sha256(p['id'].encode()).hexdigest()[:4],16)%9)*.075)/10)*10)
 p['style']='Contemporary' if re.search(r'modern|contemporary',name) else 'Traditional' if re.search(r'traditional|classic',name) else 'Natural' if re.search(r'rattan|jute|woven|wood',name) else 'Everyday'
 p['sourceImage']=p.get('sourceImage') or p.get('imageUrls',[''])[0]
 p['description']=p['description'].replace('CertiPUR-US certified','source-described CertiPUR-US certified')
# Place diverse contemporary furniture at the beginning of each department.
priority=lambda p:(0 if p['department']=='living-room' and re.search('armchair|accent chair|sofa',p['name'],re.I) else 1,0 if 'Rivet' in p['name'] else 1,p['id'])
items.sort(key=priority)
